const rows = msg.payload;
const seen = new Map();

function esc(s) {
  return String(s == null ? '' : s).replace(/'/g, "''");
}

for (const row of rows) {
  const hourStart = new Date(row.hour_start).toISOString();
  const codeEPW = row.device_code;
  const codeALL = row.device_code.replace('_EPW_', '_ALL_');
  const deviceName = esc(row.device_name);
  // Flat keys matching the existing cctv_people_* convention — merged into
  // traffic_countings.data (|| below), never replacing cctv_intrusion or
  // any other key already there for this (iddevice, starthour) row.
  const dataJson = esc(JSON.stringify({
    cctv_apd: row.hourly_apd,
    cctv_apd_total: row.daily_apd_total,
  }));

  seen.set(`${codeEPW}__${hourStart}`, `('${codeEPW}', '${deviceName}', '${hourStart}', '${dataJson}'::jsonb)`);
  seen.set(`${codeALL}__${hourStart}`, `('${codeALL}', '${deviceName}', '${hourStart}', '${dataJson}'::jsonb)`);
}

if (seen.size === 0) {
  node.warn('No APD rows to sync');
  return null;
}

const values = [...seen.values()].join(', ');

msg.query = `
  INSERT INTO traffic_countings (iddevice, device_name, starthour, data)
  VALUES ${values}
  ON CONFLICT (iddevice, starthour) DO UPDATE
    SET data = traffic_countings.data || EXCLUDED.data,
        updated_at = now()
`;

flow.set('apdSyncedRows', rows.map(r => ({ device_id: r.device_id, hour_start: r.hour_start })));
return msg;

const pairs = flow.get('apdSyncedRows');
if (!pairs || pairs.length === 0) return null;

const tuples = pairs
  .map(p => `('${p.device_id}', '${new Date(p.hour_start).toISOString()}'::timestamptz)`)
  .join(', ');

msg.query = `UPDATE apd_hourly SET is_synced = true WHERE (device_id, hour_start) IN (${tuples})`;
return msg;

